import app
import subprocess

base_config = {}
exec(subprocess.check_output(['git', 'show', 'HEAD:config.py'], text=True), base_config)
staged_default = app.DETAILED_REPORT
for label, default in [('HEAD default', base_config['DETAILED_REPORT']), ('staged default', staged_default)]:
    app.DETAILED_REPORT = default
    for values in [[], [2, 4]]:
        for mode in [None, False, True]:
            try:
                result = repr(app.report(values, detailed=mode))
            except Exception as exc:
                result = f'{type(exc).__name__}: {exc}'
            print(f'{label}; report({values}, detailed={mode}) -> {result}')
app.DETAILED_REPORT = staged_default
PY"

